-- =============================================================================
-- IELTS Academic Simulator — Supabase schema
-- =============================================================================
-- HOW TO USE
--   1. Create a free project at https://supabase.com
--   2. Open the project → SQL Editor → New query
--   3. Paste this whole file and click RUN
--   4. Copy your Project URL and anon key (Settings → API) into
--      supabase-config.js in this repository, then commit.
--
-- WHAT THIS SETS UP
--   profiles     one row per user (teacher or student). Teachers get a class
--                code; students are linked to a teacher by teacher_id.
--   progress     latest band scores + history snapshot per student.
--   submissions  each scored Writing/Speaking attempt, kept for the teacher.
--   feedback     messages a teacher sends to one of their students.
--   homework     tasks a teacher sets for a student, which the student sees on
--                their home page and marks as done.
--
-- SECURITY (row-level security is ON for every table)
--   A student can only ever read/write their OWN rows.
--   A teacher can only read rows belonging to students in THEIR class, and can
--   only send feedback to those students. Nobody can read anyone else's data,
--   even though the anon key in the app is public — that key only ever acts as
--   the logged-in user.
-- =============================================================================

-- ---------------------------------------------------------------- tables ----
create table if not exists public.profiles (
  id          uuid primary key references auth.users on delete cascade,
  email       text,
  full_name   text,
  role        text not null default 'student' check (role in ('student','teacher')),
  teacher_id  uuid references public.profiles(id) on delete set null,
  class_code  text unique,
  created_at  timestamptz not null default now()
);

create table if not exists public.progress (
  student_id  uuid primary key references public.profiles(id) on delete cascade,
  scores      jsonb not null default '{}'::jsonb,
  history     jsonb not null default '[]'::jsonb,
  updated_at  timestamptz not null default now()
);

create table if not exists public.submissions (
  id          uuid primary key default gen_random_uuid(),
  student_id  uuid not null references public.profiles(id) on delete cascade,
  module      text not null,             -- writing | speaking | reading | listening
  task        text,                      -- task1 | task2 | part1 ...
  prompt      text,
  content     text,
  band        numeric,
  report      jsonb,
  created_at  timestamptz not null default now()
);

create table if not exists public.feedback (
  id          uuid primary key default gen_random_uuid(),
  student_id  uuid not null references public.profiles(id) on delete cascade,
  teacher_id  uuid not null references public.profiles(id) on delete cascade,
  message     text not null,
  created_at  timestamptz not null default now(),
  read_at     timestamptz
);

create table if not exists public.homework (
  id            uuid primary key default gen_random_uuid(),
  teacher_id    uuid not null references public.profiles(id) on delete cascade,
  student_id    uuid not null references public.profiles(id) on delete cascade,
  title         text not null,
  module        text,                    -- listening | reading | writing | speaking | practice
  instructions  text,
  due_at        timestamptz,
  created_at    timestamptz not null default now(),
  done_at       timestamptz,
  student_note  text
);

create index if not exists homework_student_idx on public.homework(student_id, created_at desc);
create index if not exists homework_teacher_idx on public.homework(teacher_id, created_at desc);
create index if not exists submissions_student_idx on public.submissions(student_id, created_at desc);
create index if not exists feedback_student_idx    on public.feedback(student_id, created_at desc);
create index if not exists profiles_teacher_idx    on public.profiles(teacher_id);

-- ------------------------------------------------------------- functions ----
-- Helper used by policies. SECURITY DEFINER so a teacher can test "is this my
-- student?" without needing blanket read access to the profiles table.
create or replace function public.is_my_student(sid uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.profiles
    where id = sid and teacher_id = auth.uid()
  );
$$;

-- Creates the profile row automatically whenever someone signs up. Role and
-- name come from the sign-up metadata sent by the app. Teachers are given a
-- random 6-character class code that students use to join.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_role text := coalesce(new.raw_user_meta_data->>'role', 'student');
begin
  if v_role not in ('student','teacher') then
    v_role := 'student';
  end if;

  insert into public.profiles (id, email, full_name, role, class_code)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data->>'full_name', ''),
    v_role,
    case when v_role = 'teacher'
         then upper(substr(replace(gen_random_uuid()::text,'-',''), 1, 6))
         else null end
  )
  on conflict (id) do nothing;

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- A student calls this once with the code their teacher gives them. SECURITY
-- DEFINER so the lookup works without exposing the whole teacher list.
create or replace function public.join_class(p_code text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_teacher uuid;
  v_name    text;
begin
  select id, full_name into v_teacher, v_name
  from public.profiles
  where class_code = upper(trim(p_code)) and role = 'teacher';

  if v_teacher is null then
    raise exception 'That class code does not match any teacher.';
  end if;

  update public.profiles
     set teacher_id = v_teacher
   where id = auth.uid() and role = 'student';

  return coalesce(nullif(v_name,''), 'your teacher');
end;
$$;

-- --------------------------------------------------------------- policies ---
alter table public.profiles    enable row level security;
alter table public.progress    enable row level security;
alter table public.submissions enable row level security;
alter table public.feedback    enable row level security;

-- profiles -------------------------------------------------------------------
drop policy if exists profiles_select_own      on public.profiles;
drop policy if exists profiles_select_students on public.profiles;
drop policy if exists profiles_insert_own      on public.profiles;
drop policy if exists profiles_update_own      on public.profiles;

create policy profiles_select_own on public.profiles
  for select using (id = auth.uid());

-- direct column comparison (no sub-query on profiles) so there is no recursion
create policy profiles_select_students on public.profiles
  for select using (teacher_id = auth.uid());

create policy profiles_insert_own on public.profiles
  for insert with check (id = auth.uid());

create policy profiles_update_own on public.profiles
  for update using (id = auth.uid()) with check (id = auth.uid());

-- progress -------------------------------------------------------------------
drop policy if exists progress_rw_own        on public.progress;
drop policy if exists progress_select_class  on public.progress;

create policy progress_rw_own on public.progress
  for all using (student_id = auth.uid()) with check (student_id = auth.uid());

create policy progress_select_class on public.progress
  for select using (public.is_my_student(student_id));

-- submissions ----------------------------------------------------------------
drop policy if exists submissions_rw_own       on public.submissions;
drop policy if exists submissions_select_class on public.submissions;

create policy submissions_rw_own on public.submissions
  for all using (student_id = auth.uid()) with check (student_id = auth.uid());

create policy submissions_select_class on public.submissions
  for select using (public.is_my_student(student_id));

-- feedback -------------------------------------------------------------------
drop policy if exists feedback_select_student on public.feedback;
drop policy if exists feedback_update_student on public.feedback;
drop policy if exists feedback_select_teacher on public.feedback;
drop policy if exists feedback_insert_teacher on public.feedback;

create policy feedback_select_student on public.feedback
  for select using (student_id = auth.uid());

-- students may only mark their own messages as read
create policy feedback_update_student on public.feedback
  for update using (student_id = auth.uid()) with check (student_id = auth.uid());

create policy feedback_select_teacher on public.feedback
  for select using (teacher_id = auth.uid());

create policy feedback_insert_teacher on public.feedback
  for insert with check (teacher_id = auth.uid() and public.is_my_student(student_id));

-- homework -------------------------------------------------------------------
alter table public.homework enable row level security;

drop policy if exists homework_select_student on public.homework;
drop policy if exists homework_update_student on public.homework;
drop policy if exists homework_select_teacher on public.homework;
drop policy if exists homework_insert_teacher on public.homework;
drop policy if exists homework_update_teacher on public.homework;
drop policy if exists homework_delete_teacher on public.homework;

create policy homework_select_student on public.homework
  for select using (student_id = auth.uid());

-- a student may tick their own task off (and leave a note with it), nothing else
create policy homework_update_student on public.homework
  for update using (student_id = auth.uid()) with check (student_id = auth.uid());

create policy homework_select_teacher on public.homework
  for select using (teacher_id = auth.uid());

create policy homework_insert_teacher on public.homework
  for insert with check (teacher_id = auth.uid() and public.is_my_student(student_id));

create policy homework_update_teacher on public.homework
  for update using (teacher_id = auth.uid()) with check (teacher_id = auth.uid());

create policy homework_delete_teacher on public.homework
  for delete using (teacher_id = auth.uid());

-- -----------------------------------------------------------------------------
-- RE-RUNNING THIS FILE IS SAFE
-- Every statement is create-if-not-exists or drop-then-create, so pasting the
-- whole file again after an update adds what is new and leaves your data alone.
-- If you set the project up before the homework table existed, running it once
-- more is all that is needed.
--
-- THIS FILE IS ONLY HALF THE SETUP
-- It gets the reads right, but it does not limit which columns of their own
-- rows a user may write -- and a student's own profile row includes `role` and
-- `teacher_id`. Run 02_roles_and_tasks.sql next; see supabase/README.md.
-- -----------------------------------------------------------------------------


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 02_roles_and_tasks.sql

-- =============================================================================
-- IELTS Academic Simulator — role boundaries and homework integrity
-- -----------------------------------------------------------------------------
-- Run this AFTER 01_schema.sql, in the same SQL Editor, the same way.
-- Re-running it is safe: every statement replaces or recreates.
--
-- WHY THIS FILE EXISTS
-- 01_schema.sql gets the reads right — no student can see another student, no
-- teacher can see outside their class. What it does not do is limit WHICH
-- COLUMNS of their own rows a user may write, and "your own row" turns out to
-- include some things that are not theirs to decide. Against the schema as it
-- stands, all four of these succeed:
--
--   update profiles  set role = 'teacher'      -- a student promotes themselves
--   update profiles  set teacher_id = <uuid>   -- joins a class with no code
--   update homework  set title = 'nothing'     -- rewrites the task they were set
--   delete from submissions                    -- hides the essay from marking
--
-- None of them is an exotic attack; each is one line in the browser console of
-- a signed-in student. This file closes all four and gives back, as explicit
-- functions, the few things they legitimately covered.
-- =============================================================================


-- ============================================================ 1. PROFILES ===
-- role, teacher_id and class_code decide what the app shows you and whose data
-- you can reach, so they stop being user-writable. Column-level privileges are
-- the right tool: a policy can only say yes or no to the whole row, while this
-- says "you may edit your name, and nothing else".
--
-- The functions further down are SECURITY DEFINER, so they run as the owner and
-- are unaffected by this revoke — which is exactly how the legitimate changes
-- still happen.

revoke update on public.profiles from authenticated;
revoke update on public.profiles from anon;
grant  update (full_name) on public.profiles to authenticated;


-- One generator for class codes, so the trigger, the client fallback and the
-- regenerate button cannot drift apart. The alphabet leaves out I, O, 0 and 1:
-- a code is read aloud or copied off a whiteboard, and those four are where
-- that goes wrong.
create or replace function public.new_class_code()
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  v_code text;
  v_try  int := 0;
begin
  loop
    v_code := '';
    for i in 1..6 loop
      v_code := v_code || substr(v_alphabet, 1 + floor(random() * length(v_alphabet))::int, 1);
    end loop;
    exit when not exists (select 1 from public.profiles where class_code = v_code);
    v_try := v_try + 1;
    if v_try > 50 then
      raise exception 'Could not find a free class code. Try again.';
    end if;
  end loop;
  return v_code;
end;
$$;


-- Same trigger as before, now using the shared generator and tolerating a
-- collision instead of failing the sign-up.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_role text := coalesce(new.raw_user_meta_data->>'role', 'student');
begin
  if v_role not in ('student','teacher') then
    v_role := 'student';
  end if;

  insert into public.profiles (id, email, full_name, role, class_code)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data->>'full_name', ''),
    v_role,
    case when v_role = 'teacher' then public.new_class_code() else null end
  )
  on conflict (id) do nothing;

  return new;
end;
$$;


-- --------------------------------------------------------- class membership --
-- join_class already existed; it is repeated here so that it, leave_class and
-- remove_student read as one set, and so this file can be run against a project
-- created from an older copy of the schema.
create or replace function public.join_class(p_code text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_teacher uuid;
  v_name    text;
  v_role    text;
begin
  select role into v_role from public.profiles where id = auth.uid();
  if v_role is null then
    raise exception 'Your profile has not been created yet. Reload the page and try again.';
  end if;
  -- Previously a teacher could call this: the update matched nothing but the
  -- function still returned a name, so the app reported a class had been
  -- joined when none had.
  if v_role <> 'student' then
    raise exception 'Only a student account can join a class.';
  end if;

  select id, full_name into v_teacher, v_name
  from public.profiles
  where class_code = upper(trim(p_code)) and role = 'teacher';

  if v_teacher is null then
    raise exception 'That class code does not match any teacher.';
  end if;

  update public.profiles set teacher_id = v_teacher where id = auth.uid();

  return coalesce(nullif(v_name,''), 'your teacher');
end;
$$;


-- A student can no longer clear teacher_id by hand, so leaving needs a door of
-- its own. Their work stays where it is; only the link goes.
create or replace function public.leave_class()
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.profiles
     set teacher_id = null
   where id = auth.uid() and role = 'student';
end;
$$;


-- The teacher's side of the same door: removing someone who joined by mistake,
-- or who has left the course.
create or replace function public.remove_student(p_student uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (select 1 from public.profiles where id = auth.uid() and role = 'teacher') then
    raise exception 'Only a teacher can remove a student.';
  end if;
  if not exists (select 1 from public.profiles where id = p_student and teacher_id = auth.uid()) then
    raise exception 'That student is not in your class.';
  end if;
  update public.profiles set teacher_id = null where id = p_student;
end;
$$;


-- A leaked code is worth changing, and until now nothing could change it.
-- Students already linked stay linked — teacher_id is what the class is made
-- of, the code is only the way in.
create or replace function public.regenerate_class_code()
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_code text;
begin
  if not exists (select 1 from public.profiles where id = auth.uid() and role = 'teacher') then
    raise exception 'Only a teacher has a class code.';
  end if;
  v_code := public.new_class_code();
  update public.profiles set class_code = v_code where id = auth.uid();
  return v_code;
end;
$$;


-- Picking the wrong button on the sign-up form should not mean a dead account,
-- but a role change is also not something to allow on an account that is
-- already part of a class and has work in it. So: only while the account is
-- still empty.
create or replace function public.switch_role(p_role text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_me public.profiles;
begin
  if p_role not in ('student','teacher') then
    raise exception 'Role must be student or teacher.';
  end if;

  select * into v_me from public.profiles where id = auth.uid();
  if v_me.id is null then
    raise exception 'Your profile has not been created yet. Reload the page and try again.';
  end if;
  if v_me.role = p_role then
    return p_role;
  end if;

  if v_me.teacher_id is not null
     or exists (select 1 from public.profiles    where teacher_id = v_me.id)
     or exists (select 1 from public.submissions where student_id = v_me.id)
     or exists (select 1 from public.homework    where student_id = v_me.id or teacher_id = v_me.id)
     or exists (select 1 from public.feedback    where student_id = v_me.id or teacher_id = v_me.id)
  then
    raise exception 'This account is already in use as a %. Create a separate account for the other role.', v_me.role;
  end if;

  update public.profiles
     set role = p_role,
         class_code = case when p_role = 'teacher'
                           then coalesce(v_me.class_code, public.new_class_code())
                           else null end
   where id = auth.uid();

  return p_role;
end;
$$;


-- =========================================================== 2. HOMEWORK ====
-- A student must be able to tick a task off and leave a note with it, and must
-- not be able to touch anything else on the row. RLS cannot express that — it
-- judges rows, not columns — and column grants cannot either, because teacher
-- and student are the same database role here. A trigger can.
--
-- It pins rather than rejects: a student sending a whole row back (which is
-- what a PATCH of several fields is) gets their tick recorded and the rest
-- quietly restored, instead of an error they can do nothing about.

create or replace function public.homework_student_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() = old.student_id and auth.uid() <> old.teacher_id then
    new.id           := old.id;
    new.teacher_id   := old.teacher_id;
    new.student_id   := old.student_id;
    new.title        := old.title;
    new.module       := old.module;
    new.instructions := old.instructions;
    new.due_at       := old.due_at;
    new.created_at   := old.created_at;
  end if;
  return new;
end;
$$;

drop trigger if exists homework_student_guard_trg on public.homework;
create trigger homework_student_guard_trg
  before update on public.homework
  for each row execute function public.homework_student_guard();


-- ======================================================== 3. SUBMISSIONS ====
-- "for all" gave students DELETE as well, so an essay could be removed from
-- under the teacher between being scored and being read. A submission is a
-- record of an attempt: write it once, then it stands.

drop policy if exists submissions_rw_own      on public.submissions;
drop policy if exists submissions_select_own  on public.submissions;
drop policy if exists submissions_insert_own  on public.submissions;

create policy submissions_select_own on public.submissions
  for select using (student_id = auth.uid());

create policy submissions_insert_own on public.submissions
  for insert with check (student_id = auth.uid());


-- =========================================================== 4. PROGRESS ====
-- Progress is a live mirror of the browser, so update belongs here — but
-- delete does not: wiping the row is wiping every band the teacher can see.

drop policy if exists progress_rw_own     on public.progress;
drop policy if exists progress_select_own on public.progress;
drop policy if exists progress_insert_own on public.progress;
drop policy if exists progress_update_own on public.progress;

create policy progress_select_own on public.progress
  for select using (student_id = auth.uid());

create policy progress_insert_own on public.progress
  for insert with check (student_id = auth.uid());

create policy progress_update_own on public.progress
  for update using (student_id = auth.uid()) with check (student_id = auth.uid());


-- ============================================================ 5. FEEDBACK ===
-- Same shape as homework: the student's only legitimate write is marking a
-- note read, and nothing stopped them rewriting the note itself.

create or replace function public.feedback_student_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() = old.student_id and auth.uid() <> old.teacher_id then
    new.id         := old.id;
    new.teacher_id := old.teacher_id;
    new.student_id := old.student_id;
    new.message    := old.message;
    new.created_at := old.created_at;
  end if;
  return new;
end;
$$;

drop trigger if exists feedback_student_guard_trg on public.feedback;
create trigger feedback_student_guard_trg
  before update on public.feedback
  for each row execute function public.feedback_student_guard();


-- -----------------------------------------------------------------------------
-- WHAT A STUDENT CAN NOW WRITE
--   profiles     their own full_name
--   progress     their own scores and history
--   submissions  new rows for themselves; no edits, no deletions
--   homework     done_at and student_note on their own tasks
--   feedback     read_at on notes addressed to them
--   and, through functions: join a class with a valid code, or leave one
--
-- WHAT A TEACHER CAN NOW WRITE
--   profiles     their own full_name; their class code via regenerate_class_code
--   homework     anything, on tasks they set for students in their class
--   feedback     new notes to students in their class
--   and, through functions: remove a student from their class
-- -----------------------------------------------------------------------------


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 03_history_visibility.sql

-- =============================================================================
-- IELTS Academic Simulator — who may read a student's own work back
-- -----------------------------------------------------------------------------
-- Run this AFTER 01_schema.sql and 02_roles_and_tasks.sql, in the same SQL
-- Editor, the same way. Re-running it is safe: every statement replaces,
-- recreates, or is add-if-missing.
--
-- WHY THIS FILE EXISTS
-- Every scored attempt is already kept in `submissions` — the essay as it was
-- written, the Speaking transcripts, and now the Reading and Listening answer
-- sheets. Until now only the teacher ever read them back: the student's own
-- work was written once and disappeared.
--
-- Giving it back to the student is the point of this file, and the reason it
-- needs a switch is that "show every student their own history" is not a
-- decision an app should make for a classroom. A teacher may want a paper kept
-- back until it has been marked in class, or one student held out while the
-- rest of the group has it. So the teacher owns the switch:
--
--   profiles.history_default   on a TEACHER row — the class-wide setting
--   profiles.history_override  on a STUDENT row — null follows the class,
--                              true/false overrides it for that one student
--
-- and the rule is enforced in row-level security, not in the page. A student
-- who is not allowed to read their history cannot read it from the browser
-- console either, which is the only version of this switch worth having.
-- =============================================================================


-- ============================================================= 1. COLUMNS ===
alter table public.profiles add column if not exists history_default  boolean not null default true;
alter table public.profiles add column if not exists history_override boolean;

comment on column public.profiles.history_default is
  'Teacher rows: may the students in this class read their own submission history? Ignored on a student row.';
comment on column public.profiles.history_override is
  'Student rows: null = follow the teacher''s history_default; true/false = decided for this student alone.';

-- Neither column is the user's to write. 02_roles_and_tasks.sql already
-- revoked table-level UPDATE on profiles and granted back only full_name, so a
-- column added afterwards is unwritable by default -- this repeats the grant so
-- the rule still holds if the files are ever run out of order.
revoke update on public.profiles from authenticated;
revoke update on public.profiles from anon;
grant  update (full_name) on public.profiles to authenticated;


-- =========================================================== 2. THE RULE ====
-- One function, consulted by the policy and by the app, so the page and the
-- database can never disagree about what a student is allowed to see.
--
-- A student with no teacher is self-studying: nobody else owns their work, so
-- it is theirs to read. Otherwise the override decides if it is set, and the
-- class-wide default decides if it is not.
--
-- SECURITY DEFINER because the student must not be able to read their teacher's
-- profile row directly, only the one boolean that follows from it. The guard
-- keeps that narrow: you may ask about yourself, or about your own student.
create or replace function public.history_visible_to(p_student uuid)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_teacher  uuid;
  v_override boolean;
  v_default  boolean;
begin
  if p_student is null then
    return false;
  end if;

  select teacher_id, history_override
    into v_teacher, v_override
    from public.profiles
   where id = p_student;

  if not found then
    return false;
  end if;

  -- Only the student themselves, or the teacher whose class they are in, has
  -- any business asking. Anyone else is told "no" rather than the truth.
  if p_student <> auth.uid() and (v_teacher is null or v_teacher <> auth.uid()) then
    return false;
  end if;

  if v_override is not null then
    return v_override;
  end if;

  if v_teacher is null then
    return true;                        -- self-study: their own work is theirs
  end if;

  select history_default into v_default from public.profiles where id = v_teacher;
  return coalesce(v_default, true);
end;
$$;

-- The policy below runs this as the querying user, so EXECUTE has to stay.
-- The guard inside is what keeps it from being an oracle.
grant execute on function public.history_visible_to(uuid) to authenticated;

-- What the student's own page asks on sign-in. Takes no argument, so it cannot
-- be pointed at anyone else.
create or replace function public.can_see_my_history()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.history_visible_to(auth.uid());
$$;

grant execute on function public.can_see_my_history() to authenticated;


-- ======================================================== 3. THE POLICY =====
-- 02_roles_and_tasks.sql split submissions into select-own and insert-own, and
-- deliberately gave students no UPDATE and no DELETE: a submission is a record
-- of an attempt, so it is written once and then it stands. That is unchanged.
-- What changes is that reading it back is now conditional.
--
-- INSERT is untouched on purpose. A student whose history is switched off still
-- records every attempt for their teacher; they simply cannot read it back.
-- Switching it on later reveals the whole history, not just what came after.
drop policy if exists submissions_select_own on public.submissions;

create policy submissions_select_own on public.submissions
  for select using (
    student_id = auth.uid()
    and public.history_visible_to(auth.uid())
  );

-- The teacher's view is unchanged and unconditional: submissions_select_class
-- from 01_schema.sql still lets them read everything in their own class. The
-- switch decides what the STUDENT sees, never what the teacher sees.


-- ====================================================== 4. THE TEACHER'S ====
--                                                           TWO SWITCHES
-- Both are functions rather than columns for the same reason as join_class:
-- the column is not writable, and the check belongs next to the write.

-- The class-wide setting. Applies to every student who is following the class
-- default -- anyone given an explicit yes or no keeps it.
create or replace function public.set_class_history(p_on boolean)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_on is null then
    raise exception 'Pass true or false.';
  end if;
  if not exists (select 1 from public.profiles where id = auth.uid() and role = 'teacher') then
    raise exception 'Only a teacher can change this setting.';
  end if;

  update public.profiles set history_default = p_on where id = auth.uid();
  return p_on;
end;
$$;

grant execute on function public.set_class_history(boolean) to authenticated;


-- The exception for one student. Passing null puts them back on the class
-- default rather than freezing today's value into their row -- so a teacher who
-- later flips the class switch moves them too, which is what "follow the class"
-- has to mean for the setting to be worth having.
create or replace function public.set_student_history(p_student uuid, p_value boolean)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (select 1 from public.profiles where id = auth.uid() and role = 'teacher') then
    raise exception 'Only a teacher can change this setting.';
  end if;
  if not exists (select 1 from public.profiles where id = p_student and teacher_id = auth.uid()) then
    raise exception 'That student is not in your class.';
  end if;

  update public.profiles set history_override = p_value where id = p_student;
  return public.history_visible_to(p_student);
end;
$$;

grant execute on function public.set_student_history(uuid, boolean) to authenticated;


-- -----------------------------------------------------------------------------
-- WHAT CHANGED FOR EACH ROLE
--   student   may read their own submissions only while their teacher allows
--             it; still records every attempt either way; still cannot edit or
--             delete one, and still cannot see anybody else's
--   teacher   reads their whole class as before, and now owns two switches:
--             set_class_history(bool) for the group,
--             set_student_history(id, bool|null) for one student
--
-- A project set up before this file existed gets history_default = true, so
-- running it turns the history ON for every class. Turn it off from the
-- My class tab if that is not what you want.
-- -----------------------------------------------------------------------------


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 04_audio_library.sql

-- =============================================================================
-- IELTS Academic Simulator — the class's Listening audio library
-- -----------------------------------------------------------------------------
-- Run this AFTER 01, 02 and 03, in the same SQL Editor, the same way. Re-running
-- it is safe.
--
-- WHY THIS FILE EXISTS
-- The Listening generator needs four real recordings, one per section. Until
-- now every student had to find them: attach four files from their own
-- computer, or configure a Google Drive folder, an OAuth client and a Google
-- sign-in of their own. That is a teacher's job, done once.
--
-- So each teacher gets one library, in a private Storage bucket:
--
--   listening-audio/<teacher id>/section-1/…mp3
--                                section-2/…
--                                section-3/…
--                                section-4/…
--
-- The teacher uploads into it from the app (My class → Listening audio
-- library). Their students' Listening tab draws one recording at random from
-- each section — no files, no Google account, no settings.
--
-- WHO CAN DO WHAT
--   a teacher   reads, uploads, replaces and deletes in their own folder only
--   a student   reads their own teacher's folder, and nothing else
--   anyone else nothing — the bucket is private, not public: official IELTS
--               recordings are copyrighted, and this keeps them inside the
--               class rather than on an open URL
-- =============================================================================


-- ============================================================= 1. BUCKET ====
-- 18 MB per file: the most Gemini accepts inline in one request, which is how
-- the generator sends a section's audio. A larger file would upload fine and
-- then fail at generation time, which is the worse place to find out.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('listening-audio', 'listening-audio', false, 18874368,
        array['audio/mpeg','audio/mp3','audio/mp4','audio/x-m4a','audio/aac',
              'audio/wav','audio/x-wav','audio/wave','audio/ogg','audio/webm','audio/flac'])
on conflict (id) do update
   set public             = false,
       file_size_limit    = excluded.file_size_limit,
       allowed_mime_types = excluded.allowed_mime_types;


-- ========================================================= 2. THE OWNER =====
-- Whose library this user sees: their own if they teach, their teacher's if
-- they are in a class, nobody's otherwise. SECURITY DEFINER so a student can
-- learn their teacher's id without reading the teacher's profile row.
create or replace function public.audio_library_owner()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select case when role = 'teacher' then id::text else teacher_id::text end
    from public.profiles
   where id = auth.uid();
$$;

grant execute on function public.audio_library_owner() to authenticated;

create or replace function public.is_teacher()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.profiles where id = auth.uid() and role = 'teacher');
$$;

grant execute on function public.is_teacher() to authenticated;


-- ========================================================== 3. POLICIES =====
-- The first folder of every path is the teacher's id; storage.foldername()
-- splits the path, and [1] is that folder.
drop policy if exists listening_audio_read   on storage.objects;
drop policy if exists listening_audio_insert on storage.objects;
drop policy if exists listening_audio_update on storage.objects;
drop policy if exists listening_audio_delete on storage.objects;

create policy listening_audio_read on storage.objects
  for select to authenticated
  using (
    bucket_id = 'listening-audio'
    and (storage.foldername(name))[1] = public.audio_library_owner()
  );

create policy listening_audio_insert on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'listening-audio'
    and public.is_teacher()
    and (storage.foldername(name))[1] = auth.uid()::text
  );

-- Update is what an upload that replaces a same-named file needs.
create policy listening_audio_update on storage.objects
  for update to authenticated
  using (
    bucket_id = 'listening-audio'
    and public.is_teacher()
    and (storage.foldername(name))[1] = auth.uid()::text
  )
  with check (
    bucket_id = 'listening-audio'
    and public.is_teacher()
    and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy listening_audio_delete on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'listening-audio'
    and public.is_teacher()
    and (storage.foldername(name))[1] = auth.uid()::text
  );

-- -----------------------------------------------------------------------------
-- MOVING YOUR DRIVE AUDIOS HERE
-- Download the folder from Google Drive (right-click → Download gives a zip),
-- then in the app open My class → Listening audio library and add each
-- section's files to its column. Several files can be chosen at once.
-- -----------------------------------------------------------------------------


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 05_ecyr_platform.sql

-- =============================================================================
-- ECYR English platform — learner progress + AI Coach usage
-- -----------------------------------------------------------------------------
-- Runs after 01–04 (the IELTS Simulator schema, shared by the whole platform).
-- Safe to re-run: create-if-not-exists / drop-then-create throughout.
--
--   learner_state   one row per user: the platform's progress document (XP,
--                   streak, completed units/topics/readings, activity…).
--                   The app is local-first and merges this on sign-in.
--   ai_usage        per-user, per-day counter for the AI Coach, so the
--                   project's Gemini quota cannot be drained by one account.
-- =============================================================================

-- Fails early with a clear message when 01–04 have not been run yet.
do $$
begin
  if to_regclass('public.profiles') is null or to_regprocedure('public.is_my_student(uuid)') is null then
    raise exception 'Run 01_schema.sql … 04_audio_library.sql first (or use supabase/setup.sql, which includes everything).';
  end if;
end;
$$;

-- ------------------------------------------------------------ learner_state --
create table if not exists public.learner_state (
  user_id     uuid primary key references public.profiles(id) on delete cascade,
  state       jsonb not null default '{}'::jsonb,
  updated_at  timestamptz not null default now()
);

alter table public.learner_state enable row level security;

drop policy if exists learner_state_rw_own      on public.learner_state;
drop policy if exists learner_state_select_class on public.learner_state;

-- A learner reads and writes only their own document.
create policy learner_state_rw_own on public.learner_state
  for all using (user_id = auth.uid()) with check (user_id = auth.uid());

-- A teacher may read (never write) the documents of their own students.
create policy learner_state_select_class on public.learner_state
  for select using (public.is_my_student(user_id));

-- Guards against oversized documents (the app keeps it well under 256 KB).
alter table public.learner_state drop constraint if exists learner_state_size;
alter table public.learner_state
  add constraint learner_state_size check (pg_column_size(state) < 512 * 1024);

-- ----------------------------------------------------------------- ai_usage --
create table if not exists public.ai_usage (
  user_id  uuid not null references public.profiles(id) on delete cascade,
  day      date not null default current_date,
  calls    integer not null default 0,
  primary key (user_id, day)
);

alter table public.ai_usage enable row level security;

drop policy if exists ai_usage_select_own on public.ai_usage;
create policy ai_usage_select_own on public.ai_usage
  for select using (user_id = auth.uid());
-- No insert/update policy: the counter only moves through bump_ai_usage().

-- Counts one AI Coach call for the caller and refuses past the daily limit.
-- SECURITY DEFINER so it can write the counter the caller cannot touch.
create or replace function public.bump_ai_usage(p_limit integer default 40)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_calls integer;
begin
  if auth.uid() is null then
    raise exception 'not signed in' using errcode = '28000';
  end if;

  insert into public.ai_usage (user_id, day, calls)
  values (auth.uid(), current_date, 1)
  on conflict (user_id, day) do update set calls = public.ai_usage.calls + 1
  returning calls into v_calls;

  if v_calls > greatest(1, least(p_limit, 500)) then
    raise exception 'daily AI limit reached' using errcode = 'P0001';
  end if;
  return v_calls;
end;
$$;

revoke all on function public.bump_ai_usage(integer) from public;
grant execute on function public.bump_ai_usage(integer) to authenticated;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 06_api_grants.sql

-- =============================================================================
-- Explicit Data API grants
-- -----------------------------------------------------------------------------
-- Older Supabase projects grant every new table in `public` to the API roles
-- automatically. Newer projects may not ("expose new tables" off), and then a
-- signed-in user gets "permission denied for table …" even with correct RLS.
-- These grants make the schema work either way. Row-level security still
-- decides WHICH rows each user can touch; a grant only lets the query reach it.
--
-- profiles is deliberately NOT granted UPDATE here: 02/03 allow updating only
-- full_name (column grant), so role / teacher_id / class_code stay locked.
-- Safe to re-run.
-- =============================================================================

grant usage on schema public to authenticated;

grant select, insert                  on public.profiles      to authenticated;
grant select, insert, update, delete  on public.progress      to authenticated;
grant select, insert, update, delete  on public.submissions   to authenticated;
grant select, insert, update, delete  on public.feedback      to authenticated;
grant select, insert, update, delete  on public.homework      to authenticated;
grant select, insert, update, delete  on public.learner_state to authenticated;
grant select                          on public.ai_usage      to authenticated;

-- Re-assert the column rule for profiles in case an earlier blanket grant exists.
revoke update on public.profiles from authenticated, anon;
grant  update (full_name) on public.profiles to authenticated;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 07_portfolio.sql

-- =============================================================================
-- ECYR English platform — "Mis trabajos" (portfolio)
-- -----------------------------------------------------------------------------
-- Runs after 01–06. Safe to re-run: create-if-not-exists / drop-then-create /
-- on-conflict-update throughout.
--
-- WHY THIS FILE EXISTS
-- Learners arrive with work they have ALREADY done — essays, homework, tests,
-- projects, certificates, recordings, photos of notebook pages. This gives each
-- account one place to keep it, and gives their teacher a way to read it and
-- leave a review.
--
--   portfolio_items   one row per piece of work: what it is, metadata, an
--                     optional pasted text and/or an optional file in Storage,
--                     plus the teacher's review.
--   portfolio/        private Storage bucket, one folder per user:
--                       portfolio/<user id>/<uuid>-<file name>
--
-- WHO CAN DO WHAT
--   the owner     reads, adds, edits (metadata only) and deletes their own
--                 items and files; can NOT write the teacher's review
--   their teacher reads the items and files of students in their class, and
--                 reviews through review_portfolio_item(); never edits or
--                 deletes the student's work
--   anyone else   nothing — no anon access at all
-- =============================================================================

-- Fails early with a clear message when 01–04 have not been run yet.
do $$
begin
  if to_regclass('public.profiles') is null or to_regprocedure('public.is_my_student(uuid)') is null then
    raise exception 'Run 01_schema.sql … 06_api_grants.sql first (or use supabase/setup.sql, which includes everything).';
  end if;
end;
$$;


-- ============================================================== 1. TABLE ====
create table if not exists public.portfolio_items (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references public.profiles(id) on delete cascade,
  kind          text not null default 'other'
                constraint portfolio_kind check (kind in ('writing','homework','test','project','certificate','audio','image','other')),
  title         text not null
                constraint portfolio_title_len check (char_length(btrim(title)) between 1 and 200),
  description   text
                constraint portfolio_description_len check (char_length(description) <= 2000),
  level         text
                constraint portfolio_level check (level is null or level in ('A1','A2','B1','B2','C1')),
  skill         text
                constraint portfolio_skill check (skill is null or skill in ('listening','reading','writing','speaking','grammar','vocabulary')),
  done_at       date,
  -- Self-reported mark: a percentage or an IELTS band. The scale is required
  -- whenever there is a score, so "7" can never be ambiguous.
  score         numeric,
  score_scale   text
                constraint portfolio_score_scale check (score_scale is null or score_scale in ('percent','band')),
  text_content  text
                constraint portfolio_text_len check (char_length(text_content) <= 60000),
  file_path     text,
  file_name     text
                constraint portfolio_file_name_len check (char_length(file_name) <= 255),
  file_type     text
                constraint portfolio_file_type_len check (char_length(file_type) <= 255),
  file_size     integer
                constraint portfolio_file_size check (file_size is null or file_size between 0 and 20971520),
  source        text not null default 'upload'
                constraint portfolio_source check (source in ('upload','migration','import')),
  teacher_note  text
                constraint portfolio_teacher_note_len check (char_length(teacher_note) <= 4000),
  teacher_score numeric
                constraint portfolio_teacher_score check (teacher_score is null or teacher_score between 0 and 100),
  reviewed_by   uuid references public.profiles(id) on delete set null,
  reviewed_at   timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

-- Cross-column rules, drop-then-add so a re-run picks up any change.
-- coalesce(..., false) matters: a CHECK that evaluates to NULL passes, and
-- "score_scale = 'percent'" is NULL when there is no scale at all.
alter table public.portfolio_items drop constraint if exists portfolio_score_valid;
alter table public.portfolio_items add constraint portfolio_score_valid check (
  score is null
  or coalesce(
       (score_scale = 'percent' and score between 0 and 100)
       or (score_scale = 'band' and score between 0 and 9),
       false)
);

-- A row may only point at a file inside its owner's own folder, so nobody can
-- "attach" somebody else's object to their item.
alter table public.portfolio_items drop constraint if exists portfolio_file_in_own_folder;
alter table public.portfolio_items add constraint portfolio_file_in_own_folder check (
  file_path is null or file_path like user_id::text || '/%'
);

create index if not exists portfolio_items_user_idx on public.portfolio_items(user_id, created_at desc);

-- updated_at follows every write. A trigger assigning NEW needs no column
-- privilege, so it works under the column grants below.
create or replace function public.portfolio_touch()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists portfolio_touch_trg on public.portfolio_items;
create trigger portfolio_touch_trg
  before update on public.portfolio_items
  for each row execute function public.portfolio_touch();


-- ======================================================== 2. ROW SECURITY ===
alter table public.portfolio_items enable row level security;

drop policy if exists portfolio_select_own   on public.portfolio_items;
drop policy if exists portfolio_insert_own   on public.portfolio_items;
drop policy if exists portfolio_update_own   on public.portfolio_items;
drop policy if exists portfolio_delete_own   on public.portfolio_items;
drop policy if exists portfolio_select_class on public.portfolio_items;

create policy portfolio_select_own on public.portfolio_items
  for select to authenticated using (user_id = auth.uid());

create policy portfolio_insert_own on public.portfolio_items
  for insert to authenticated with check (user_id = auth.uid());

create policy portfolio_update_own on public.portfolio_items
  for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

create policy portfolio_delete_own on public.portfolio_items
  for delete to authenticated using (user_id = auth.uid());

-- A teacher reads (never writes) the work of students in their own class.
create policy portfolio_select_class on public.portfolio_items
  for select to authenticated using (public.is_my_student(user_id));


-- ========================================================= 3. COLUMN GRANTS =
-- Policies judge whole rows; which COLUMNS the owner may write is a privilege
-- question, so it is answered the way 02 answers it for profiles: revoke the
-- table-wide grant (Supabase hands one out to anon/authenticated by default on
-- new tables) and grant back an explicit column list.
--
-- Left out on purpose:
--   teacher_note, teacher_score, reviewed_by, reviewed_at — the review; only
--       review_portfolio_item() (SECURITY DEFINER, runs as owner) writes them
--   user_id (update) — an item cannot be moved to another account
--   file_* (update) — a file is attached when the item is created; replacing
--       it means deleting and re-uploading, so a row never points at an object
--       that was not uploaded with it
--   id, created_at, updated_at — set by defaults / trigger
--
-- Teacher and student are the same database role (authenticated), so a
-- column grant cannot tell them apart — which is fine, because neither writes
-- the review columns directly.
revoke all on public.portfolio_items from anon;
revoke all on public.portfolio_items from authenticated;

grant usage on schema public to authenticated;
grant select, delete on public.portfolio_items to authenticated;
grant insert (user_id, kind, title, description, level, skill, done_at, score, score_scale,
              text_content, file_path, file_name, file_type, file_size, source)
  on public.portfolio_items to authenticated;
grant update (kind, title, description, level, skill, done_at, score, score_scale, text_content)
  on public.portfolio_items to authenticated;


-- ============================================================= 4. REVIEW ====
-- The teacher's one write. Checks the item belongs to one of the caller's
-- students, validates the score against the item's own scale (band 0–9 when
-- the student used bands, otherwise 0–100), and stamps who/when.
-- Passing null for both note and score clears the review.
create or replace function public.review_portfolio_item(p_id uuid, p_note text, p_score numeric)
returns public.portfolio_items
language plpgsql
security definer
set search_path = public
as $$
declare
  v_item public.portfolio_items;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  if auth.uid() is null then
    raise exception 'not signed in' using errcode = '28000';
  end if;

  select * into v_item from public.portfolio_items where id = p_id;
  -- Same answer for "does not exist" and "not yours to review", so the
  -- function cannot be used to probe other classes' item ids.
  if v_item.id is null or not public.is_my_student(v_item.user_id) then
    raise exception 'That work is not from a student in your class.' using errcode = '42501';
  end if;

  if v_note is not null and char_length(v_note) > 4000 then
    raise exception 'The review note is too long (4000 characters max).';
  end if;
  if p_score is not null then
    if v_item.score_scale = 'band' and (p_score < 0 or p_score > 9) then
      raise exception 'A band score must be between 0 and 9.';
    elsif p_score < 0 or p_score > 100 then
      raise exception 'The score must be between 0 and 100.';
    end if;
  end if;

  update public.portfolio_items
     set teacher_note  = v_note,
         teacher_score = p_score,
         reviewed_by   = case when v_note is null and p_score is null then null else auth.uid() end,
         reviewed_at   = case when v_note is null and p_score is null then null else now() end
   where id = p_id
  returning * into v_item;

  return v_item;
end;
$$;

revoke all on function public.review_portfolio_item(uuid, text, numeric) from public;
revoke all on function public.review_portfolio_item(uuid, text, numeric) from anon;
grant execute on function public.review_portfolio_item(uuid, text, numeric) to authenticated;


-- ============================================================ 5. STORAGE ====
-- 20 MB per file: comfortably fits a phone photo, a scanned PDF or a few
-- minutes of audio, without turning the bucket into video hosting.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('portfolio', 'portfolio', false, 20971520,
        array[
          -- documents
          'application/pdf',
          'application/msword',
          'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
          'application/vnd.oasis.opendocument.text',
          'text/plain','text/markdown','text/x-markdown',
          'application/rtf','text/rtf',
          -- images (photos of notebook pages, certificates)
          'image/png','image/jpeg','image/webp','image/heic','image/heif',
          -- audio recordings
          'audio/mpeg','audio/mp3','audio/mp4','audio/x-m4a','audio/m4a','audio/aac',
          'audio/wav','audio/x-wav','audio/wave','audio/webm','audio/ogg','application/ogg',
          -- short video (e.g. a recorded presentation)
          'video/mp4','video/webm'
        ])
on conflict (id) do update
   set public             = false,
       file_size_limit    = excluded.file_size_limit,
       allowed_mime_types = excluded.allowed_mime_types;

-- The first folder of every path is the owner's id; storage.foldername()
-- splits the path, and [1] is that folder.
drop policy if exists portfolio_obj_insert_own   on storage.objects;
drop policy if exists portfolio_obj_select_own   on storage.objects;
drop policy if exists portfolio_obj_delete_own   on storage.objects;
drop policy if exists portfolio_obj_select_class on storage.objects;

create policy portfolio_obj_insert_own on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'portfolio'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy portfolio_obj_select_own on storage.objects
  for select to authenticated
  using (
    bucket_id = 'portfolio'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy portfolio_obj_delete_own on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'portfolio'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

-- No UPDATE policy: uploads never overwrite (every object name carries a fresh
-- uuid), so there is nothing legitimate for one to allow.

-- The teacher reads their students' folders. The CASE guards the uuid cast:
-- a folder name that is not a uuid is simply "not my student", never an error
-- that would break the listing for everyone else.
create policy portfolio_obj_select_class on storage.objects
  for select to authenticated
  using (
    bucket_id = 'portfolio'
    and case
          when (storage.foldername(name))[1] ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            then public.is_my_student(((storage.foldername(name))[1])::uuid)
          else false
        end
  );

-- -----------------------------------------------------------------------------
-- WHAT EACH ROLE CAN NOW DO
--   owner     portfolio_items: read / add / delete own rows; edit kind, title,
--             description, level, skill, done_at, score, score_scale and
--             text_content of own rows. Storage: upload, read and delete inside
--             portfolio/<own id>/.
--   teacher   reads the items and files of students in their class; writes
--             only teacher_note / teacher_score through
--             review_portfolio_item(id, note, score).
--
-- NOTE: deleting an account removes its rows (on delete cascade) but not its
-- Storage objects; remove the folder from the dashboard if needed.
-- -----------------------------------------------------------------------------


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 08_migrations_log.sql

-- =============================================================================
-- ECYR English — migrations log ("Importar y migrar", route /import)
-- -----------------------------------------------------------------------------
-- Runs after 01–06. Safe to re-run: create-if-not-exists / drop-then-create.
--
--   migrations_log   one row per import a learner ran: what came in (summary,
--                    used by the app to avoid importing the same thing twice
--                    and to list past imports) and the full imported data
--                    (payload: the old IELTS account dump — feedback and
--                    homework from the old teacher have nowhere else to live —
--                    the session file's bands/history, or the progress file).
--
-- Rows are append-only for the learner: insert + read their own, never update
-- or delete. Their teacher can read them (is_my_student), like progress.
--
-- Submissions: no change needed. 02 replaced submissions_rw_own with
-- submissions_insert_own (WITH CHECK student_id = auth.uid()) and 06 grants
-- INSERT on every column to authenticated, so a student may insert their own
-- rows with an explicit created_at (the migration preserves the original
-- date). Reading them back stays subject to 03's history visibility; the app
-- therefore also remembers migrated submission keys in this log.
-- =============================================================================

-- Fails early with a clear message when the earlier files have not been run yet.
do $$
begin
  if to_regclass('public.profiles') is null or to_regprocedure('public.is_my_student(uuid)') is null then
    raise exception 'Run 01_schema.sql … 06_api_grants.sql first (or use supabase/setup.sql, which includes everything).';
  end if;
end;
$$;

create table if not exists public.migrations_log (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references public.profiles(id) on delete cascade,
  source      text not null check (source in ('ielts-account','ielts-session-file','ecyr-progress-file')),
  summary     jsonb not null default '{}'::jsonb,
  payload     jsonb,
  created_at  timestamptz not null default now()
);

create index if not exists migrations_log_user_idx on public.migrations_log(user_id, created_at desc);

-- Size guards (the app trims the payload under 1.8 MB before sending it).
alter table public.migrations_log drop constraint if exists migrations_log_payload_size;
alter table public.migrations_log
  add constraint migrations_log_payload_size check (payload is null or pg_column_size(payload) < 2 * 1024 * 1024);
alter table public.migrations_log drop constraint if exists migrations_log_summary_size;
alter table public.migrations_log
  add constraint migrations_log_summary_size check (pg_column_size(summary) < 512 * 1024);

alter table public.migrations_log enable row level security;

drop policy if exists migrations_log_insert_own   on public.migrations_log;
drop policy if exists migrations_log_select_own   on public.migrations_log;
drop policy if exists migrations_log_select_class on public.migrations_log;

-- A learner logs only their own imports …
create policy migrations_log_insert_own on public.migrations_log
  for insert to authenticated with check (user_id = auth.uid());
-- … and reads only their own.
create policy migrations_log_select_own on public.migrations_log
  for select to authenticated using (user_id = auth.uid());
-- A teacher may read (never write) the imports of their own students.
create policy migrations_log_select_class on public.migrations_log
  for select to authenticated using (public.is_my_student(user_id));
-- No update / delete policies: the log is append-only.

-- Explicit grants (Supabase's default privileges would otherwise grant ALL).
revoke all on public.migrations_log from anon;
revoke all on public.migrations_log from authenticated;
grant select, insert on public.migrations_log to authenticated;
